WITH not_flagged AS (SELECT s.* FROM accounts s WHERE EXISTS (SELECT 1 FROM transactions x WHERE x.account_id = s.id AND x.txn_time >= s.opened_date)) SELECT CASE WHEN balance >= 62000 THEN 'LARGE' ELSE 'SMALL' END AS balance_tier, DATE_TRUNC('YEAR', opened_date) AS year_start, status, SIZE(COLLECT_SET(status)) AS num_status, COUNT(*) FILTER (WHERE account_type = 'SAVINGS') AS savings_rows, SUM(balance) AS total_balance, SUM(CASE WHEN status = 'OPEN' THEN balance ELSE 0 END) AS open_balance FROM not_flagged GROUP BY CASE WHEN balance >= 62000 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('YEAR', opened_date), status ORDER BY year_start DESC NULLS FIRST;
